      "Charmayne heads both the Intellectual Property (IP) practice and the Technology, Media and Telecommunications (TMT) practice. Aside from IP and TMT, her practice also has a strong focus on data protection. Charmayne works with regulators, associations and companies of all sizes in shaping the future of IP, TMT and data protection.",
      "Charmayne’s areas of practice include managing the registration of and general advisory and drafting work relating to the classic forms of IP rights (trademark, copyright, industrial design rights and patents). She deals with regulators and advises clients who provide technology and telecommunications services such as satellite, internet and on-demand content services on regulatory compliance and licensing matters.",
      "She also advises various multinational and local companies on data protection issues including compliance with data protection laws and strategic response to data breach incidents, including guiding clients through data breach reporting requirements and supporting clients in highly regulated sectors.",
      "She is the Malaysian member of the Global Leaders Forum (TMT practice) and a member of the Federation of Malaysian Manufacturers (FMM) (for IP and TMT)."
