      "Mubashir was called to the Malaysian Bar on 23.6.1989. He has been a commercial and civil litigator for over 35 years. His portfolio comprises a wide variety of laws on domestic and international disputes. This includes fraud and asset recovery, cross-border disputes and transactions, cyber-law, blockchain disputes, investors’ claims, corporate disputes, shareholders’ disputes, aviation, insurance and re-insurance, contract, tort (particularly defamation and media law), constitutional and administrative laws and land laws.",
      "He now mainly acts as lead counsel for trials and hearings at the Malaysian High Court, Court of Appeal and Federal Court, as well as for domestic and international arbitrations. He has worked closely with clients from various jurisdictions including the United Kingdom, Germany, South Korea, Japan, Singapore and the United States.",
      "He is also a Fellow of the Chartered Institute of Arbitrators (CIArb), Malaysian Institute of Arbitrators (MIArb) and the Asian Institute of Alternative Dispute Resolution (AIADR). He is empanelled as an arbitrator in the Asian International Arbitration Centre (AIAC), Asian Institute of Alternative Dispute Resolution (AIADR) Borneo International Centre for Arbitration and Mediation (BICAM), Brunei Darussalam Arbitration Centre (BDAC), Dubai International Arbitration Centre (DIAC), Oman Commercial Arbitration Centre (OCAC), Chamber of Arbitrators, Asia Pacific International Arbitration Chamber (APIAC), as well as Maldives International Arbitration Centre (MIAC). He is a mediator too in AIADR and APIAC. In addition, he has been a member of the Disciplinary Committee appointed by the Malaysian Advocates and Solicitors’ Disciplinary Board since 21.4.2003. He has sat as Chairman of various Disciplinary Committees."
