    "overview": [
      "Nimalan is a commercial litigator with a broad practice encompassing civil and commercial litigation, company law and shareholders’ disputes, international arbitration, restructuring and insolvency, and regulatory enforcement. He has appeared at all tiers of the Malaysian Courts.",
      "He has acted in a wide range of high-value and complex commercial disputes, including claims involving breaches of contracts, directors’ and officers’ duties, and trustee duties. He has particular experience in shareholders’ disputes, including oppression actions and in winding-up proceedings.",
      "Nimalan has also appeared as co-Counsel in international arbitrations, under both the AIAC Rules and SIAC Rules. He work also includes arbitration-related court proceedings such as applications to set aside and enforce arbitral awards, and to stay court proceedings pending arbitration.",
      "In addition, Nimalan regularly acts for Bursa Malaysia Securities Berhad including in enforcement actions against listed issuers and their directors, as well as in resisting judicial review proceedings brought against the Stock Exchange."
    ],
    "keyAreas": [
      "International Arbitration",
      "Commercial Litigation and Arbitration",
      "Company Law and Shareholders’ Disputes",
      "Regulatory Enforcement",
      "Restructuring and Insolvency"
    ],
