          "Acted as junior counsel for Thai-Lao Lignite and Hongsa Lignite against the Government of Lao in order to uphold an arbitral award exceeding USD 57 million, with related enforcement proceedings in the US, the UK and France. The Federal Court decision is reported at Thai-Lao Lignite Ltd & Anor v Government of the Lao People's Democratic Republic [2017] 9 CLJ 273.",
          "Successfully acted for the foreign subsidiary of a leading global oil and services company in obtaining a stay of an oppression petition pending arbitration. This case is notable as there were no reported cases in Malaysia at the time, where the stay of an oppression action has been allowed due to an arbitration clause, or which dealt with the applicability of the Arbitration Act 2005 to a stay application premised on an arbitration agreement under the Arbitration Act 1952.",
          "Successfully obtained a stay of proceedings pending arbitration on behalf of a foreign licenced institution is respect of shareholder claims against a local financial institution. The High Court decision is reported at RUSD Investment Bank Inc & Ors v Qatar Islamic Bank & Ors [2015] 1 LNS 231.",
