          "Acted as co-counsel for Ann Joo Steel Bhd at the Federal Court in successfully preserving the validity of a High Court Order issued 1995, in defeating a collateral attack. The Federal Court found that as the Order was valid in law, any challenge to the validity of the same should have been done independently i.e., an application to set aside the said Order instead of framing it within a defence of another suit. The ensuing assessment of damages valued the claim in excess of RM 30 million. The Federal Court decision is reported at Ann Joo Steel Berhad v Pengarah Tanah dan Galian Negeri Pulau Pinang & Anor and another appeal [2020] 1 MLJ 689.",
          "Successfully acted as counsel for a private limited company in recovering a loan exceeding of RM 13 million which was advanced pursuant to an oral agreement, against the holding company, and operator of the largest lifestyle mall in Seremban.",
