          "Successfully acted as counsel at the Court of Appeal for the administrator of an estate in challenging fraudulent land transfers effected through a forged trust deed.. The High Court’s decision is reported at Leong Kim Fond v Chong Kooi Heng & Ors [2023] MLJU 2592.",
          "Acting as counsel for one of the largest wholesale gold jewellery suppliers in Malaysia in a claim for recovery of gold jewellery products in excess of RM 20 million.",
