    "overview": [
      "Sara is a partner in the firm’s Employment and Immigration practice, with extensive experience in both contentious and non-contentious employment and labour matters.",
      "She advises on a broad range of human resource and compliance issues, drawing on her knowledge across all aspects of employment law, corporate immigration law, tax, and employment-related aspects of corporate law. Her diverse client portfolio spans multiple industries, reflecting her adaptability and depth of expertise.",
      "Sara routinely handles employment disputes, including unjust dismissal claims, and provides strategic legal advice on workforce restructuring, redundancies, business closures, and voluntary or mutual separation schemes. Her practice also covers disciplinary issues, misconduct, sexual harassment, performance management, internal investigations, trade union recognition, and collective bargaining. Additionally, she supports clients with employment matters arising from mergers and acquisitions—particularly employee transitions and the integration of workplace policies, culture, and employment terms.",
      "More recently, Sara has expanded her focus to include ESG compliance, advising businesses on ethical recruitment and the management of foreign labour. She counsels on fair labour practices, working and living conditions, and alignment with International Labour Organization (ILO) standards, including indicators of forced labour and human trafficking under Protocol 29.",
      "She has been commended as being “an excellent lawyer, very responsive, and to the point” (Legal 500 Asia Pacific 2025 Edition), “practical in her advice” (Legal 500 Asia Pacific 2025 Edition) and praised for being a “proactive communicator” and “demonstrating understanding” of her clients’ business (Benchmark Litigation Asia Pacific 2025 Edition). Aside from being the sole Malaysian recipient of the Client Choice Award 2022 in the Labour and Employment category by Lexology, Sara has also been recognised for her abilities as an award recipient in the Labour, Employment & Benefits category under Lexology Index (previously Who’s Who Legal) Southeast Asia 2024 and 2025 and in the Employment & Labour category under Lexology Index Malaysia 2025.",
      "Sara’s other key practice areas also include general and civil litigation and acting for medical practitioners in negligence and malpractice matters."
    ],
