      "She is sought after by corporations to assist them in managing and navigating the social criteria in ESG requirements or guidance in Business and Human Rights; and is currently a facilitator for the Leading for Impact (LIP) programme conducted by the Institute of Corporate Directors Malaysia (ICDM) on this issue.",
      "She also provides strategic advice in internal fraud management advising clients in high profile and highly sensitive matters involving fraud perpetrated by employees; and the options available to the organisations to obtain redress against the wrongdoers.",
      "Her client base is spread across various sectors and includes regulators.",
      "Her practice extends to focused compliance on bribery and corruption."
