    "overview": [
      "Sharon Chong is a partner in the Dispute Resolution practice of Skrine, Malaysia. She has a diverse portfolio spanning international arbitration, aviation, joint venture and shareholder disputes, fraud and asset recovery, and insolvency and restructuring.",
      "She acts as advocate and counsel in a wide array of complex cross-border disputes and has appeared at all tiers of the Malaysian courts, as well as in international arbitrations across Asia and Europe. In addition to her practice as counsel, she regularly sits as arbitrator in AIAC, SIAC, and ad hoc arbitrations.",
      "Sharon is a past President of the Malaysian Institute of Arbitrators and member of the Steering Committee of the Maxwell Chambers (Singapore). She is a Fellow of both the Chartered Institute of Arbitrators (FCIArb) and the Malaysian Institute of Arbitrators (FMIArb), and is empanelled as an arbitrator with several leading international arbitration centres.",
      "Sharon is also active in the insolvency and restructuring community. She is a member of INSOL International and serves on the International Board of the International Women’s Insolvency & Restructuring Confederation (IWIRC), where she is Asia Conference Co-Director for 2026. She is additionally a founding member and Immediate Past Co-Chair of IWIRC Malaysia. In the field of advocacy, Sharon serves as faculty for both the Bar Council of Malaysia’s Advocacy Training Course and for the Delos Remote Oral Advocacy Programme (ROAP) Asia edition, where she contributes to training the next generation of advocates in international dispute resolution.",
      "Sharon has been consistently recognised by leading legal publications including Chambers Asia-Pacific, The Legal 500, Benchmark Litigation Asia-Pacific, asialaw, Global Arbitration Review, and Global Restructuring Review. Sharon’s clients have described her as “patient and thorough, but more than that, she is supportive and explains the legal position clearly at the outset”, “very good at addressing the subject matter and really easy to work with”, and is “clear-thinking and decisive” (Chambers Asia-Pacific 2023-2025). Other client feedback notes that she is “efficient, has an in-depth legal knowledge of the subject matter, and is quick in responding” and “stands out for her enthusiasm, incisive analysis of issues, and incredible commitment to the client”, “always a pleasure to work with’, “particularly impressive in terms of her enthusiasm and being available to clients”, her “skillset, integrity, intelligence and dedication to the case and client surprises all the time”, is “extremely responsive and savvy”, “gives practical and clear advice”, has “impressed” with “both her round-the-clock availability and her ability to get up to speed with sometimes complex matters” and also “very willing to roll up her sleeves and get the work done. Meticulous, with a strong work ethic and very easy to get along with” (The Legal 500 Asia-Pacific 2020-2025).",
      "Sharon is ranked Band 5 for Dispute Resolution by Chambers Asia-Pacific, recognised as a “Leading Partner” for Dispute Resolution in The Legal 500 Asia-Pacific, and named as a “Litigation Star” in Commercial Disputes, Dispute Resolution and International Arbitration by Benchmark Litigation Asia-Pacific. She is also recommended for Southeast Asia – Arbitration in the Lexology Index (formerly Who’s Who Legal), featured in The Legal 500 Arbitration Powerlist 2022 and 2023 for Southeast Asia, and listed among ALB Asia’s Top 15 Rising Lawyers 2021. She has been recognised by the Global Arbitration Review 100 (GAR 100) as a “name to know”."
    ],
