          "Advising and acting for a foreign multinational financial institution in relation to enforcement issues and arbitral proceedings (with seat in a foreign state as well as in Malaysia). Acted successfully for the client at the Federal Court where the Court confirmed, among others, that successful award-creditors have a legitimate choice of remedies and may elect to enforce arbitral awards under the REJA via a “confirmation judgment,” without this being considered “judgment laundering.”",
